import{c as e,J as l,h as r,k as o}from"./chunks/framework.WgZQdPFo.js";const c=JSON.parse('{"title":"Обзор и философия капитала","description":"Концепция единого финансового контура мастера, разделение кармана мастера и кассы цеха, автоматический расчет личных расходов через дельту капитала.","frontmatter":{"title":"Обзор и философия капитала","description":"Концепция единого финансового контура мастера, разделение кармана мастера и кассы цеха, автоматический расчет личных расходов через дельту капитала.","order":16},"headers":[],"relativePath":"ru/docs/spaces/moy-kapital/overview.md","filePath":"ru/docs/spaces/moy-kapital/overview.md","lastUpdated":1794012535000}'),s={name:"ru/docs/spaces/moy-kapital/overview.md"};function a(n,t,i,d,g,p){return l(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="обзор-и-философия-пространства-«мои-капитал»" tabindex="-1">Обзор и философия пространства «Мой капитал» <a class="header-anchor" href="#обзор-и-философия-пространства-«мои-капитал»" aria-label="Permalink to &quot;Обзор и философия пространства «Мой капитал»&quot;">​</a></h1><p>Каждый ремесленник и владелец небольшого производства рано или поздно сталкивается с одной и той же дилеммой: где заканчиваются деньги мастерской и начинаются личные средства семьи?</p><p>Если смешивать закупку кожи, оплату аренды мастерской и покупку продуктов в одном кошельке, бизнес теряет прозрачность. Становится невозможно понять, приносит ли мастерская реальную чистую прибыль или держится на плаву только за счет постоянных личных вливаний.</p><p>Пространство <strong>«Мой капитал»</strong> в составе ПРО-режима ОмниКрафт ЕРП создано как раз для того, чтобы навести идеальный порядок на границе между бизнесом и личной жизнью, не превращая мастера в уставшего бухгалтера с кипой кассовых чеков.</p><hr><h2 id="принцип-двух-контуров-цех-и-карман-мастера" tabindex="-1">Принцип двух контуров: цех и карман мастера <a class="header-anchor" href="#принцип-двух-контуров-цех-и-карман-мастера" aria-label="Permalink to &quot;Принцип двух контуров: цех и карман мастера&quot;">​</a></h2><p>Финансовая модель ОмниКрафт ЕРП разделяет потоки денег на два строгих контура:</p><ol><li><strong>Операционный контур цеха (Рабочие пространства):</strong> учет сырья на складе, калькуляция себестоимости, движение заказов на верстаке, движение денег по кассе мастерской (ДДС) и склад готовой продукции.</li><li><strong>Консолидированный контур капитала (Пространство «Мой капитал»):</strong> совокупная стоимость всех активов владельца, включая личные банковские карты, сбережения, инвестиционный портфель, оборудование, недвижимость и доли в каждом из производственных пространств.</li></ol><div class="info custom-block"><p class="custom-block-title">Независимость баз данных</p><p>Личные финансы хранятся в изолированной базе данных <code>personal_finance.db</code>. Это гарантирует, что данные о личных счетах, инвестициях и имуществе никогда не попадут в производственные отчеты конкретного цеха и останутся строго конфиденциальными.</p></div><hr><h2 id="математическая-дельта-учет-трат-без-сбора-чеков" tabindex="-1">Математическая дельта: учет трат без сбора чеков <a class="header-anchor" href="#математическая-дельта-учет-трат-без-сбора-чеков" aria-label="Permalink to &quot;Математическая дельта: учет трат без сбора чеков&quot;">​</a></h2><p>Главная инженерная находка пространства «Мой капитал» — <strong>метод расчета расходов по балансовой дельте</strong>.</p><p>Большинство программ для личных финансов требуют дисциплины робота: нужно каждый день открывать телефон и вручную заносить траты на кофе, бензин, хлеб и оплату интернета. На практике мастера хватает максимум на две недели, после чего учет забрасывается.</p><p>В ОмниКрафт ЕРП применен обратный инженерный подход:</p><p>$$\\text{Личные расходы за период} = \\text{Капитал на начало} + \\text{Доходы цеха и личные дивиденды} - \\text{Капитал на конец}$$</p><p>Вам достаточно раз в неделю или в конце месяца актуализировать остатки на нескольких основных карточках и вкладах. Программа автоматически сопоставит полученную дельту с зафиксированными операциями мастерской и вычислит точную сумму, которая ушла на личную жизнь.</p><div class="tip custom-block"><p class="custom-block-title">Спокойный сон предпринимателя</p><p>Если баланс личных счетов за месяц вырос, а чистая прибыль мастерской подтверждена движением готовой продукции и продажами, ваше дело развивается в плюс. Если же остатки тают, система подсветит непривязанный отток средств до того, как образуется кассовый разрыв.</p></div><hr><h2 id="архитектура-пространства-«мои-капитал»" tabindex="-1">Архитектура пространства «Мой капитал» <a class="header-anchor" href="#архитектура-пространства-«мои-капитал»" aria-label="Permalink to &quot;Архитектура пространства «Мой капитал»&quot;">​</a></h2><p>Интерфейс пространства организован в виде логичной 5-ступенчатой системы:</p><ul><li><strong>Счета и инвестиции:</strong> единый центр управления ликвидными деньгами. Включает две вкладки: «Счета и кошельки» (наличные, дебетовые карты, вклады, расчетная валюта и стейблкоины) и «Инвестиционный портфель» (акции, облигации, займы, доли в бизнесе).</li><li><strong>Имущество и ресурсы:</strong> материальные активы долгосрочного пользования (оборудование вне цеха, станки в долевом владении, недвижимость, автотранспорт).</li><li><strong>Личные операции:</strong> журнал крупных личных поступлений и внеплановых изъятий, влияющих на общий баланс.</li><li><strong>Сводка капитала:</strong> контрольная панель Net Worth, собирающая воедино личные активы и производственный капитал всех подключенных мастерских.</li><li><strong>Аналитика капитала:</strong> графики динамики благосостояния, валютная корзина и распределение активов по классам.</li></ul><hr><h2 id="двухуровневая-навигация-и-контекстные-панели-деиствии" tabindex="-1">Двухуровневая навигация и контекстные панели действий <a class="header-anchor" href="#двухуровневая-навигация-и-контекстные-панели-деиствии" aria-label="Permalink to &quot;Двухуровневая навигация и контекстные панели действий&quot;">​</a></h2><p>Интерфейс пространства построен по стандарту двухуровневой информационной архитектуры без визуального шума:</p><ul><li><strong>Уровень 1 (Главная навигационная полоса):</strong> расположена в верхней части экрана и служит исключительно для чистого переключения между пятью ключевыми разделами («Счета и инвестиции», «Имущество и материалы», «Важные операции», «Мой капитал», «Аналитика»). Верхняя строка избавлена от посторонних кнопок.</li><li><strong>Уровень 2 (Контекстные панели действий каждого экрана):</strong> все инструменты сгруппированы строго там, где они применяются:</li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">Экран</th><th style="text-align:left;">Расположение</th><th style="text-align:left;">Набор инструментов</th><th style="text-align:left;">Назначение</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Счета и инвестиции</strong></td><td style="text-align:left;">Напротив вкладок «Счета / Инвестиции»</td><td style="text-align:left;"><strong>📊 Статистика</strong>, <strong>💱 Курсы</strong>, <strong>⚙️ Настройки</strong>, <strong>📖 Справка</strong></td><td style="text-align:left;">Анализ валютной корзины, обновление курсов валют, настройка категорий счетов и документация по ликвидным активам.</td></tr><tr><td style="text-align:left;"><strong>Имущество и материалы</strong></td><td style="text-align:left;">Напротив фильтра категорий имущества</td><td style="text-align:left;"><strong>🛡️ Дубликаты</strong>, <strong>+ Добавить</strong>, <strong>📖 Справка</strong></td><td style="text-align:left;">Проверка коллизий долей владения (метод Гамильтона), добавление оборудования и ценностей, руководство по фондам.</td></tr><tr><td style="text-align:left;"><strong>Важные операции</strong></td><td style="text-align:left;">В шапке реестра операций</td><td style="text-align:left;"><strong>📖 Справка</strong></td><td style="text-align:left;">Руководство по фиксации внешних личных доходов и целевых крупных расходов.</td></tr><tr><td style="text-align:left;"><strong>Сводка капитала</strong></td><td style="text-align:left;">В шапке консолидированного дашборда</td><td style="text-align:left;"><strong>🔄 Обновить</strong>, <strong>📖 Справка</strong></td><td style="text-align:left;">Мгновенный пересчет сводного капитала мастера и аналитика чистых активов Net Worth.</td></tr><tr><td style="text-align:left;"><strong>Аналитика капитала</strong></td><td style="text-align:left;">В верхней строке динамики трендов</td><td style="text-align:left;"><strong>🚀 Скоро</strong>, <strong>📖 Справка</strong></td><td style="text-align:left;">Обзор динамики благосостояния и ретроспективный анализ непрерывной истории мастерских.</td></tr></tbody></table><hr><h2 id="безопасность-и-zero-api-подход" tabindex="-1">Безопасность и Zero-API подход <a class="header-anchor" href="#безопасность-и-zero-api-подход" aria-label="Permalink to &quot;Безопасность и Zero-API подход&quot;">​</a></h2><p>Вся финансовая информация обрабатывается <strong>строго на Вашем компьютере</strong>. Программа не отправляет балансы карт, суммы инвестиций или списки счетов на сторонние сервера или облачные платформы.</p><p>Обновление валютных курсов работает в один клик без привязки к платным внешним сервисам: кнопка «Обновить» автоматически опрашивает открытые международные и государственные шлюзы котировок (Европейский ЦБ, ЦБ РФ, CoinGecko). При необходимости вы также можете вручную скорректировать курс любой валюты за пару секунд или использовать ручной экспорт промпта для внешних веб-чатов.</p>',30)])])}const f=e(s,[["render",a]]);export{c as __pageData,f as default};
